from content_helpers import code, output, choice, lesson, section, program
from content_06 import with_functions, example

def sections():
    result = [section("final", "16. Университетское повторение", "Проверьте объяснения, тесты и итоговый проект.", [
        lesson("translation", "От исходника к программе", "Различайте объявление, определение и стадии сборки.",
            "Препроцессор обрабатывает директивы вроде #include; заголовок обычно предоставляет объявления и определения, которые должны быть видимы компилятору. Компиляция каждой единицы трансляции создаёт объектный код, компоновка связывает определения в программу. Объявление функции сообщает её интерфейс, определение содержит тело.\n\nЕсли вызвана объявленная обычная функция, но нужного определения нет в программе, типичная диагностика появляется на компоновке. Ошибка синтаксиса обычно обнаруживается раньше. Не все ошибки обязаны диагностироваться: UB во время выполнения может не сопровождаться предупреждением.\n\nВнешняя команда clang++ -std=c++17 main.cpp -o app компилирует и компонует; ./app запускает. Несколько исходников можно передать одной команде. Это команды разработчика, а не встроенная функция codelib. Для библиотечных имён std:: — квалификация пространства имён; #include не означает using namespace std.",
            example('int triple(int n);\nint triple(int n) { return 3 * n; }', 'std::cout << triple(4);'),
            "Слова «компилируется» и «работает правильно» не равнозначны. Интерпретатор и компилятор — способы реализации исполнения; C++ обычно использует предварительную трансляцию, но стандарт описывает поведение программы, не заставляя каждую реализацию иметь одинаковый внутренний конвейер.",
            "Объявление — интерфейс, определение — реализация. Успешная сборка не заменяет тесты требований.", [
                with_functions(code("prototype", "Восстановите интерфейс", 'Напишите объявление int shipping(int boxes); перед main и определение после main. shipping возвращает 5+2*boxes. Ввод boxes (0…100), вывод — результат.', 'int boxes = 0;\nstd::cin >> boxes;\nstd::cout << shipping(boxes);', [("3", "11"), ("0", "5"), ("1", "7"), ("100", "205"), ("50", "105")], ["Одного объявления недостаточно для готовой программы.", "И объявление, и определение должны иметь одинаковые типы параметров и результата."], "Прототип позволяет узнать имя до тела, а определение обеспечивает реализацию."), 'int shipping(int boxes);'),
                with_functions(code("namespace", "Своё пространство имён", 'Определите namespace lab с int twice(int n), возвращающей n*2. main читает n (−100…100), вызывает lab::twice и выводит результат. Не используйте глобальный using namespace.', 'int n = 0;\nstd::cin >> n;\nstd::cout << lab::twice(n);', [("4", "8"), ("-2", "-4"), ("-100", "-200"), ("0", "0"), ("100", "200")], ["Пространство имён записывается namespace lab { ... }.", "Квалифицированный вызов использует lab::twice."], "Квалификация позволяет различать одноимённые сущности разных областей."), 'namespace lab {\nint twice(int n) { return n * 2; }\n}'),
                choice("linker", "Где пропало тело?", 'Вызвана объявленная функция, но её обычного определения нет ни в одном подключённом объектном файле. Какая типичная стадия сообщает unresolved symbol?', ["Компоновка", "Только запуск", "Только ввод данных"], 0, ["Объявления хватило для анализа вызова.", "Объединить вызов с реализацией уже невозможно."], "Это типичная диагностика инструментов сборки, не обещание, что все возможные нарушения программы всегда диагностируются."),
                code("status", "Код завершения main", 'Ввод: n (−100…100). Если n≥0, выведите Accepted и завершите main через return 0. Иначе выведите Rejected и тоже return 0: в этой учебной задаче отказ — штатный результат, не ошибка процесса.', 'int n = 0;\nstd::cin >> n;\nif (n >= 0) { std::cout << "Accepted"; return 0; }\nstd::cout << "Rejected";\nreturn 0;', [("0", "Accepted"), ("-1", "Rejected"), ("100", "Accepted"), ("-100", "Rejected"), ("1", "Accepted")], ["Вывод и возвращаемый код процесса — разные каналы.", "return 0 не печатает символ 0."], "Прикладной ответ Rejected здесь не означает неуспешную работу самой программы.")
            ], ["компиляция", "компоновка", "пространства имён"]),
        lesson("testing", "Тесты и исправление ошибок", "Проверьте не только пример, но и свойство алгоритма.",
            "Тест — конкретный вход с ожидаемым результатом. Выбирайте границы, пустые случаи, равенство, отрицательные значения и случаи, которые отличают похожие алгоритмы. Для функции максимума {-8,-3,-12} обнаруживает ошибочную инициализацию нулём; {1,2,3} — нет.\n\nassert(condition) из <cassert> завершает проверочную программу при ложном условии, если проверки не отключены NDEBUG. Это инструмент разработки, не обработка ошибочного пользовательского ввода в релизе. Для гарантированных проверок продукта нужны явные ветви и результаты.\n\nМожно сравнить два независимых алгоритма на малых входах: потоковая сумма и сумма после хранения должны совпасть. Случайный тест не доказывает правильность вообще, а компилятор не проверяет смысл ожидаемого ответа.",
            example('int larger(int a, int b) { return a > b ? a : b; }', 'assert(larger(-8, -3) == -3);\nassert(larger(5, 5) == 5);\nstd::cout << "Passed";').replace('#include <iostream>', '#include <iostream>\n#include <cassert>'),
            "Санитайзер обнаруживает часть нарушений на выполненных путях, а не формально доказывает отсутствие всех ошибок. Не запускайте UB как упражнение на предсказание результата. Проверяйте, что сами тесты действительно выполняются и не отключены конфигурацией сборки.",
            "Тест должен отличать ошибочный алгоритм от правильного. Проверяйте и реализацию, и ожидаемые ответы.", [
                with_functions(code("assert", "Проверьте функцию", 'Напишите int larger(int a,int b). Без ввода выполните assert для пар (−8,−3), (5,5), (0,−1) с результатами −3,5,0. После проверок выведите Passed. В этом задании NDEBUG не определён.', 'assert(larger(-8, -3) == -3);\nassert(larger(5, 5) == 5);\nassert(larger(0, -1) == 0);\nstd::cout << "Passed";', [("", "Passed")], ["Используйте cassert и конкретные ожидаемые результаты.", "Не выводите Passed раньше выполнения всех assert."], "Проверочная программа сообщает успех после реального выполнения утверждений.", headers="iostream cassert"), 'int larger(int a, int b) {\n    if (a > b) { return a; }\n    return b;\n}'),
                code("fixmax", "Исправьте максимум", 'Ошибочный алгоритм начинает best=0 и ищет максимум. Исправьте для n (1…100) и значений (−100…100), выведите максимум. Приведите в черновике тест с одними отрицательными значениями.', 'int n = 0, best = 0;\nstd::cin >> n >> best;\nfor (int i = 1; i < n; ++i) {\n    int x = 0; std::cin >> x;\n    if (x > best) { best = x; }\n}\nstd::cout << best;', [("3 -8 -3 -12", "-3"), ("1 -100", "-100"), ("2 0 -1", "0"), ("4 -5 -5 -5 -5", "-5"), ("5 100 -100 50 -50 0", "100"), ("2 -100 -99", "-99"), ("3 7 7 7", "7")], ["Начальное значение должно принадлежать входной последовательности.", "Прочитайте первый элемент отдельно и пройдите оставшиеся n-1."], "Это сознательное возвращение к прошлому алгоритму с задачей диагностировать ошибку, а не механическое повторение.", difficulty=2),
                choice("assertrelease", "Assert в продукте", 'Почему нельзя использовать только assert для проверки недоверенного входа в релизном приложении?', ["Проверки могут быть отключены NDEBUG и не являются обычным механизмом ответа пользователю", "assert никогда не выполняется", "assert разрешён только внутри цикла"], 0, ["Режим сборки меняет поведение assert.", "У приложения должен оставаться явный путь обработки ошибки."], "Инструменты разработки не должны подменять контракт пользовательского интерфейса."),
                code("property", "Независимая сверка суммы", 'Ввод: n (0…100), n целых (−100…100). При чтении накопите sum1, сохраните vector; вторым проходом получите sum2. Если равны, выведите OK и сумму через пробел, иначе Error.', 'int n = 0;\nstd::cin >> n;\nstd::vector<int> values(n);\nint sum1 = 0;\nfor (int i = 0; i < n; ++i) { std::cin >> values[i]; sum1 += values[i]; }\nint sum2 = 0;\nfor (int value : values) { sum2 += value; }\nif (sum1 == sum2) { std::cout << "OK " << sum1; }\nelse { std::cout << "Error"; }', [("4 1 -2 7 0", "OK 6"), ("0", "OK 0"), ("1 -100", "OK -100"), ("3 100 100 100", "OK 300"), ("2 -50 50", "OK 0"), ("5 1 2 3 4 5", "OK 15")], ["Используйте два разных цикла и отдельные накопители.", "Сравнение само по себе не доказывает отсутствие общей ошибки в обоих методах."], "Дифференциальная проверка полезна, но не заменяет тесты с заранее известным результатом.", headers="iostream vector", difficulty=2)
            ], ["тестирование", "assert", "поиск ошибок"]),
        lesson("capstone", "Итоговый проект: диспетчер запасов", "Самостоятельно соедините состояние, команды и гарантии.",
            "Финальный проект — небольшой консольный диспетчер. Товары имеют имена, количество меняется командами, неуспешное списание сохраняет прежнее состояние. Используйте map для поиска по имени и класс для отдельного инварианта, если это помогает ясности. Не нужен сложный UI или необоснованные зависимости.\n\nКритерии готовности: программа компилируется в C++17/20, каждый ответ соответствует протоколу, пустой каталог допустим, повторная поставка накапливается, нехватка не уменьшает остаток, запрос отсутствующего товара не создаёт его случайно. Проверяйте последовательные команды, а не только одно состояние.\n\nПосле решения объясните вслух: где хранятся данные, какие объекты владеют ресурсами, когда ссылки перестают быть допустимыми, какой код отвечает за ввод и где подтверждается успех. Эти вопросы связывают практику с университетской теорией.",
            program('std::map<std::string, int> stock;\nstock["Food"] += 7;\nint amount = 3;\nif (stock["Food"] >= amount) { stock["Food"] -= amount; }\nstd::cout << stock["Food"];', "iostream string map"),
            "Инвариант проекта — все количества неотрицательны, а неуспешное списание не меняет состояние. Проверка этого свойства по каждому переходу даёт связное объяснение корректности. Наличие меню или класса само по себе не делает продукт надёжным; важны конкретные гарантии.",
            "Объясните контракт и проверьте несколько сценариев от начала до конца. Не называйте непроверенный путь готовой функцией.", [
                code("deliveries", "Поставки и запрос", 'Ввод: n (0…100), n пар name amount (латинское слово, amount 0…100), затем query. Сложите поставки по именам. Выведите количество query (0 при отсутствии) и число разных товаров. Запрос не должен вставлять новый товар.', 'int n = 0;\nstd::cin >> n;\nstd::map<std::string, int> stock;\nfor (int i = 0; i < n; ++i) { std::string name; int amount = 0; std::cin >> name >> amount; stock[name] += amount; }\nstd::string query; std::cin >> query;\nauto it = stock.find(query);\nint count = 0;\nif (it != stock.end()) { count = it->second; }\nstd::cout << count << " " << stock.size();', [("3 Food 2 Air 7 Food 5 Food", "7 2"), ("0 Missing", "0 0"), ("1 Box 0 Box", "0 1"), ("3 A 5 A 7 B 1 A", "12 2"), ("3 X 1 Y 2 Z 3 Y", "2 3"), ("2 A 100 A 100 A", "200 1")], ["Для поставок [] уместен, для запроса без вставки — find.", "Считайте поставки через +=, не затирайте прежнее количество."], "Разные операции над одной map имеют разные требования к вставке.", headers="iostream string map", difficulty=3),
                code("withdraw", "Списание без частичного изменения", 'Ввод: initial,first,second (0…100). Для одного товара выполните два независимых последовательных запроса списания. Каждый успешен, если хватает текущего остатка; неуспех ничего не меняет. Выведите успех первого, успех второго и окончательный остаток через пробел.', 'int count = 0, first = 0, second = 0;\nstd::cin >> count >> first >> second;\nbool success1 = false, success2 = false;\nif (first <= count) { count -= first; success1 = true; }\nif (second <= count) { count -= second; success2 = true; }\nstd::cout << success1 << " " << success2 << " " << count;', [("7 5 4", "1 0 2"), ("2 5 1", "0 1 1"), ("0 0 0", "1 1 0"), ("5 0 5", "1 1 0"), ("100 100 100", "1 0 0"), ("3 4 3", "0 1 0")], ["Второй запрос использует состояние после первого.", "Неуспешная ветвь не вычитает ничего."], "Тест 2,5,1 проверяет, что неуспех первого не портит последующий запрос.", difficulty=3),
                choice("done", "Критерий готовности", 'Диспетчер собрался и верно обработал одну поставку. Достаточно ли этого, чтобы объявить проверенными списания и сохранение файла?', ["Нет, эти сценарии нужно проверить отдельно", "Да, компилятор уже доказал всё", "Да, если интерфейс выглядит красиво"], 0, ["Неисполненные ветви могли остаться неверными.", "Каждая заявленная гарантия требует соответствующей проверки."], "Честный отчёт разделяет реализованное, проверенное и ещё не проверенное."),
                code("dispatcher", "Полный командный диспетчер", 'До 100 корректных команд: ADD name amount накапливает запас; TAKE name amount печатает OK и уменьшает запас, если хватает, иначе Missing без изменения; GET name печатает текущий запас или 0; STOP завершает. Имена — латинские слова, amount 0…100. Каждый ответ с переносом. Для отсутствующего товара TAKE всегда Missing, даже при amount=0. Неизвестных команд нет.', 'std::map<std::string, int> stock;\nstd::string command;\nwhile (std::cin >> command) {\n    if (command == "STOP") { break; }\n    std::string name; std::cin >> name;\n    if (command == "ADD") {\n        int amount = 0; std::cin >> amount; stock[name] += amount;\n    } else if (command == "GET") {\n        auto it = stock.find(name);\n        if (it == stock.end()) { std::cout << "0\\n"; }\n        else { std::cout << it->second << "\\n"; }\n    } else if (command == "TAKE") {\n        int amount = 0; std::cin >> amount;\n        auto it = stock.find(name);\n        if (it != stock.end() && it->second >= amount) {\n            it->second -= amount; std::cout << "OK\\n";\n        } else { std::cout << "Missing\\n"; }\n    }\n}', [("GET Food ADD Food 7 TAKE Food 5 TAKE Food 4 GET Food STOP", "0\nOK\nMissing\n2\n"), ("TAKE None 0 STOP", "Missing\n"), ("ADD Air 2 ADD Air 3 GET Air STOP", "5\n"), ("STOP", ""), ("ADD Food 1 GET Food TAKE Food 2 GET Food STOP", "1\nMissing\n1\n")], ["Разберите команду, потом её аргументы согласно протоколу.", "Для TAKE используйте find и проверку остатка до изменения. GET не должен вставлять."], "Итоговый проект объединяет строки, map, цикл, условие, короткое замыкание и неразрушающую обработку неуспеха.", headers="iostream string map", difficulty=3)
            ], ["итоговый проект", "протокол", "инварианты"])
    ])]
    result[0]["lessons"][0]["exercises"][0]["solution"] += '\nint shipping(int boxes) { return 5 + 2 * boxes; }\n'
    return result
